functions {
  /**
   * Maps unconstrained R^(K-1) vector x to Unit Vector S^(K-1).
   *
   * @param x Unconstrained vector of length K-1
   * @param K Dimension of the embedding space (output vector size)
   * @return Unit vector of length K
   */
  vector hyper_tanh_to_unit_jacobian(vector x, int K) {
    vector[K] y;
    real r = 1.0;

    for (i in 1:K - 2) {
      real val = x[i];
      y[i] = r * tanh(val);
      real cosh_val = cosh(val);
      r = r * inv(cosh_val);
      real power = K - i; 
      jacobian += -power * log(cosh_val);
    }

    real last_x = x[K-1];
    jacobian += log(2.0) - log1p(square(last_x));

    real denom = 1.0 + square(last_x);

    y[K-1] = r * (1.0 - square(last_x)) / denom;
    y[K] = r * (2.0 * last_x) / denom;

    return y;
  }
}

data {
  int&lt;lower=2&gt; K;
}

parameters {
  vector[K - 1] x_raw; // Unconstrained
}

transformed parameters {
  vector[K] mu = hyper_tanh_to_unit_jacobian(x_raw, K);
}

model {
  // uniform on the sphere
}

Score function
The following Stan model implements the multiple \(\tau\) code.


Show the code
functions{
  matrix kronecker(matrix A, matrix B) {
    matrix[rows(A) * rows(B), cols(A) * cols(B)] C;
    int m = rows(A);
    int n = cols(A);
    int p = rows(B);
    int q = cols(B);
    for (i in 1:m) {
      for (j in 1:n) {
        int row_start = (i - 1) * p + 1;
        int row_end = (i - 1) * p + p;
        int col_start = (j - 1) * q + 1;
        int col_end = (j - 1) * q + q;
        C[row_start:row_end, col_start:col_end] = A[i, j] * B;
      }
    }
   return C;
}

  vector q_loss(real q, vector u){
    return (abs(u) + (2 * q - 1) * u);
 }

  vector score(vector q, vector y, matrix x, array[] vector beta) {
    int N = num_elements(y);
    int P = num_elements(beta[ , 1]);
    int K = num_elements(q);
    matrix[K, P] out;

    for (k in 1:K) {
      out[k] = transpose(transpose(x) * q_loss(q[k], y - x * to_vector(beta[ ,k])));
    }

    return to_vector(out);
  }

  matrix make_w (matrix x, vector q) {
    int N = rows(x);
    int P = cols(x);
    int m = num_elements(q);
    matrix[m * P, m * P] out;

    matrix[m, m] Q;
    matrix[P, P] G = crossprod(x) ;

  //  G[1:P, 1] /= log(N);
  //  G[1, 2:P] = transpose(G[2:P, 1]);

    for (i in 1:m) {
      Q[i, i] = q[i] * (1 - q[i]);
      for (j in 1:i - 1) {
        Q[i, j] = min([q[i], q[j]]) - q[i] * q[j];
        Q[j, i] = Q[i, j];
      }
    }

    return kronecker(N * inverse(G), inverse(Q));
  }
}
data {
  int N;               // Number of observation
  int P;               // Number of predictors
  int K;               // Number of quantiles
  vector[K] q;
  vector[N] y;         
  matrix[N, P] x;
}
transformed data {
  matrix[K * P, K * P] W = make_w(x, q);
}
parameters {
  // can add ordered constraint here
   array[P] vector[K] beta;
   real&lt;lower=0&gt; sigma;
}
model {
  vector[K * P] score_vec = score(q, y, x, beta) / sigma;

  for (i in 1:K) 
    beta[, i] ~ normal(0, 4);

  sigma ~ exponential(1);

  target += -quad_form(W, score_vec) / (2 * N * K) - K * N * log(sigma);

}


