Appendix
Single tau
functions {
  real vasicek_quantile_lpdf(vector y, real theta, vector mu, real tau) {
    int N = num_elements(y);
    real lpdf = 0.5 * N * (log1m(theta) - log(theta));
    vector[N] qnorm_mu = inv_Phi(mu);
    real qnorm_tau = inv_Phi(tau);
    vector[N] qnorm_y = inv_Phi(y);
    vector[N] qnorm_alpha = -sqrt(theta) * qnorm_tau + 
                              qnorm_mu * sqrt(1 - theta);

    return lpdf + 0.5 * dot_self(qnorm_y) - 
            0.5 * sum( (sqrt(1 - theta) * qnorm_y - qnorm_alpha)^2 / theta);
  }
}
data {
  int&lt;lower=0&gt; N;
  vector[N] y;
  vector[N] x;
  real&lt;lower=0, upper=1&gt; tau;
} 
parameters {
  real alpha;
  real beta;
  real sigma;
} 
model {
  alpha ~ normal(0, 4);
  beta ~ normal(0, 4);
  sigma ~ normal(0, 2);
  y ~ vasicek_quantile(inv_logit(sigma), inv_logit(alpha + beta * x), tau);
}
Multiple tau
functions {
  real vasicek_quantile_lpdf(vector y, real theta, vector mu, real tau) {
    if (tau &lt;= 0 || tau &gt;= 1) 
      reject("tau must be between 0 and 1 found tau = ", tau);

    if (theta &lt;= 0 || theta &gt;= 1) 
      reject("theta must be between 0 and 1 found theta = ", theta);

    int N = num_elements(y);
    real lpdf = 0.5 * N * (log1m(theta) - log(theta));
    vector[N] qnorm_mu = inv_Phi(mu);
    real qnorm_tau = inv_Phi(tau);
    vector[N] qnorm_y = inv_Phi(y);
    vector[N] qnorm_alpha = -sqrt(theta) * qnorm_tau +  
                              qnorm_mu * sqrt(1 - theta);

    return lpdf + 
            0.5 * dot_self(qnorm_y) - 
            0.5 * sum( (sqrt(1 - theta) * qnorm_y - qnorm_alpha)^2 / theta);
  }
}
data {
  int&lt;lower=0&gt; N;
  vector[N] y;
  vector[N] x;

  int&lt;lower=1&gt; K;
  vector&lt;lower=0, upper=1&gt;[K] tau;
} 
parameters {
  vector[K] alpha;
  vector[K] beta;
  vector[K] sigma;
} 
model {
  alpha ~ normal(0, 4);
  beta ~ normal(0, 4);
  sigma ~ normal(0, 2);

  for (i in 1:K)
    y ~ vasicek_quantile(inv_logit(sigma[i]), 
                         inv_logit(alpha[i] + beta[i] * x), tau[i]);
}

Score function
The following Stan model implements the single \(\tau\) code. I’ll simulate some data and compare to the asymmetric Laplace:


Show the code
functions{
  vector q_loss(real q, vector u){
    return 0.5 * (abs(u) + (2 * q - 1) * u);
  }

  vector score(real q, vector y, matrix x, vector beta) {
    return transpose(x) * q_loss(q, y - x * beta );
  }

  matrix make_w (matrix x, real q) {
    int N = rows(x);
    int P = cols(x);
    real alpha = 1 / (q * (1 - q));
    matrix[P, P] x_out = inverse_spd(crossprod(x));

    return alpha * x_out * N;
  }
}
data {
  int N;                 // Number of observation
  int P;                 // Number of predictors
  real q;
  vector[N] y;           // Response variable sorted
  matrix[N, P] x;
}
transformed data {
  matrix[P, P] W = make_w(x, q);
}
parameters {
  vector[P] beta;
}
model {
  vector[P] score_vec = score(q, y, x, beta);

  beta ~ normal(0, 4);

  target += -quad_form(W, score_vec) / (2 * N);
}


